import numpy as np
from scipy.optimize import minimize

def f(params):
    x, y, z = params
    if x*y + y*z + z*x == 0:
        return float('inf')
    return (2*x**2 + 1) * (2*y**2 + 1) * (2*z**2 + 1) / (x*y + y*z + z*x)

# Grid search
n_steps = 50
x_range = np.linspace(0.1, 5.0, n_steps)
y_range = np.linspace(0.1, 5.0, n_steps)
z_range = np.linspace(0.1, 5.0, n_steps)

min_val = float('inf')
best_coords = (0, 0, 0)

for x in x_range:
    for y in y_range:
        for z in z_range:
            val = f((x, y, z))
            if val < min_val:
                min_val = val
                best_coords = (x, y, z)

print(f"Grid Search Minimum: {min_val} at {best_coords}")

# Refine with scipy
res = minimize(f, best_coords, bounds=[(0.001, None), (0.001, None), (0.001, None)])
print(f"Scipy Refinement: {res.fun} at {res.x}")

