import numpy as np
from scipy.optimize import minimize
import random

def f(params):
    x, y, z = params
    if x*y + y*z + z*x == 0:
        return float('inf')
    return (2*x**2 + 1) * (2*y**2 + 1) * (2*z**2 + 1) / (x*y + y*z + z*x)

best_val = float('inf')
best_coords = None

# Try a variety of starting points
for _ in range(100):
    # Random points in a reasonably large range
    start = (random.uniform(0.1, 5.0), random.uniform(0.1, 5.0), random.uniform(0.1, 5.0))
    res = minimize(f, start, bounds=[(1e-6, None), (1e-6, None), (1e-6, None)])
    if res.success and res.fun < best_val:
        best_val = res.fun
        best_coords = res.x

print(f"Randomized Multi-start Minimum: {best_val} at {best_coords}")

